const isos = [$('Next backlog (courses, chapters)').first().json.iso, $('Next backlog (lessons)').first().json.iso].filter(Boolean).sort();
if (!isos.length) return [];
const LANG = {da:767,es:1056,et:10154,fr:673,it:734,lt:10152,lv:10153,ms:749,sv:754,th:753,nl:737,no:760,pt:708,ro:770,de:666,id:757,pl:748,ko:733};
const iso = isos[0];
if (!LANG[iso]) throw new Error('No Lokalise language id for ' + iso);
return [{ json: { iso, lang_id: LANG[iso] } }];

const L = $('Pick language').first().json; const iso = L.iso;
const APPLY = /^(courses|lessons|chapters)[.]/;
const gid = n => String(n).split('.').slice(0,2).join('.');
const all = $('Backlog rows').all().map(i => i.json || {}).filter(r => r.id && r.iso === iso && APPLY.test(String(r.key_name || '')));
const failed = new Set($('Failed rows').all().map(i => i.json || {}).filter(r => r.key_name).map(r => gid(r.key_name)));
const byKey = {}; const superseded = [];
for (const r of all) { const k = String(r.key_id); const p = byKey[k]; if (!p) { byKey[k] = r; continue; } if (String(r.createdAt) > String(p.createdAt)) { superseded.push(p); byKey[k] = r; } else superseded.push(r); }
const ORDER = ['courses','lessons','chapters'];
const rows = Object.values(byKey).sort((a, b) => { const pa = a.key_name.split('.'), pb = b.key_name.split('.'); return ORDER.indexOf(pa[0]) - ORDER.indexOf(pb[0]) || (parseInt(pa[1]) || 0) - (parseInt(pb[1]) || 0) || a.key_name.localeCompare(b.key_name); });
// Whole groups only (e.g. chapters.12.title + chapters.12.content), about 450 keys per night.
const CAP = 450; const batch = []; const held = []; let lastG = null;
for (const r of rows) { const g = gid(r.key_name);
  if (failed.has(g)) { held.push({ id: r.id, status: 'held', reason: String('held: another key in ' + g + ' failed checks | ' + (r.reason || '')).slice(0, 300) }); continue; }
  if (batch.length >= CAP && g !== lastG) break;
  batch.push({ id: r.id, key_id: r.key_id, key_name: r.key_name, group: g, current_text: r.current_text, proposed_text: r.proposed_text, reason: r.reason || '' }); lastG = g; }
return [{ json: { iso, lang_id: L.lang_id, batch, held, superseded: superseded.map(r => ({ id: r.id, status: 'superseded', reason: String('older duplicate proposal | ' + (r.reason || '')).slice(0, 300) })), apply_ids: batch.length ? batch.map(r => r.key_id).join(',') : '0' } }];

const P = $('Plan batch').first().json; const live = $input.first().json; const iso = P.iso;
const INTERNAL = new Set(['maria@efuturemedia.com','maria+devs@efuturemedia.com','kseniya.krasovskaya@efuturemedia.com','raul@efuturemedia.com','support@lokalise.com','']);
const ok = Array.isArray(live.keys);
const byId = {}; if (ok) for (const k of live.keys) { const t = (k.translations || []).find(x => x.language_iso === iso); if (t) byId[k.key_id] = t; }
const rows = P.batch.map(r => Object.assign({}, r, { status: ok ? 'to_apply' : 'proposed' })); const demoted = new Set();
for (const r of rows) { if (r.status !== 'to_apply') continue;
  const t = byId[r.key_id];
  if (!t) { r.status = 'held'; r.reason = 'live re-check: translation not found | ' + r.reason; demoted.add(r.group); continue; }
  const ed = String(t.modified_by_email || '').toLowerCase();
  if (!INTERNAL.has(ed)) { r.status = 'skipped_linguist'; r.reason = 'edited by ' + ed + ' since the scan | ' + r.reason; demoted.add(r.group); continue; }
  if (t.translation !== r.current_text) { r.status = 'skipped_changed'; r.reason = 'text changed since the scan | ' + r.reason; demoted.add(r.group); continue; } }
for (const r of rows) if (r.status === 'to_apply' && demoted.has(r.group)) { r.status = 'held'; r.reason = 'held: another key in ' + r.group + ' changed since the scan | ' + r.reason; }
const writes = rows.filter(r => r.status === 'to_apply');
const body = { keys: writes.map(r => ({ key_id: r.key_id, translations: [{ language_iso: iso, translation: r.proposed_text }] })) };
return [{ json: { rows, live_ok: ok, n_write: writes.length, body: JSON.stringify(body) } }];

const P = $('Plan batch').first().json; const D = $('Decide writes').first().json;
let w = null; try { if ($('Write to Lokalise').isExecuted) w = $('Write to Lokalise').first().json; } catch (e) {}
const okIds = new Set(); const errs = {};
if (w && Array.isArray(w.keys)) for (const k of w.keys) okIds.add(String(k.key_id));
if (w && Array.isArray(w.errors)) for (const e of w.errors) { const id = e.key_id || (e.key || {}).key_id; if (id) errs[String(id)] = e.message || JSON.stringify(e).slice(0, 120); }
const wErr = w && !Array.isArray(w.keys) ? JSON.stringify(w.error || w).slice(0, 150) : '';
const rows = D.rows.map(r => { if (r.status !== 'to_apply') return r; const id = String(r.key_id);
  if (okIds.has(id) && !errs[id]) return Object.assign({}, r, { status: 'applied' });
  return Object.assign({}, r, { status: 'apply_error', reason: 'write failed: ' + (errs[id] || wErr || 'no confirmation') + ' | ' + r.reason }); });
const updates = rows.filter(r => r.status !== 'proposed').map(r => ({ id: r.id, status: r.status, reason: String(r.reason || '').slice(0, 300) })).concat(P.held, P.superseded);
const c = s => rows.filter(r => r.status === s).length;
return [{ json: { iso: P.iso, updates, batch: rows.length, applied: c('applied'), held: c('held') + P.held.length, skipped: c('skipped_linguist') + c('skipped_changed'), errors: c('apply_error'), live_ok: D.live_ok } }];

const NL = String.fromCharCode(10);
const F = $('Finalize').first().json; const iso = F.iso;
const NAMES = {da:'Danish',nl:'Dutch',et:'Estonian',fr:'French',de:'German',id:'Indonesian',it:'Italian',ko:'Korean',lv:'Latvian',lt:'Lithuanian',ms:'Malay',no:'Norwegian',pl:'Polish',pt:'Brazilian Portuguese',ro:'Romanian',es:'Spanish',sv:'Swedish',th:'Thai'};
const url = 'https://efuturemedia.app.n8n.cloud/projects/dEuUcqimhxflYu8w/datatables/p8ryr5LxWpLuZUzA';
const lines = [
  '*Members MT backlog, nightly apply: ' + (NAMES[iso] || iso) + ' (' + iso + ')*',
  F.live_ok === false ? 'The live check in Lokalise failed, so nothing was written. It will retry tomorrow night.' : null,
  '• Applied to Lokalise: ' + F.applied + ' of ' + F.batch + ' course, lesson and chapter keys',
  '• Held for review (to keep a group consistent or failed checks): ' + F.held,
  '• Skipped, edited by a linguist since the scan: ' + F.skipped,
  F.errors ? '• Write errors: ' + F.errors : null,
  'Results: <' + url + '|members_mt_rewrite_proposals> (filter iso = ' + iso + ')'
].filter(Boolean);
return [{ json: { text: lines.join(NL) } }];
